refentry.refsect1:
&reftitle.description;

 public mixedYaf_Config_Ini::key


Retourne la clé de l'entrée de configuration courante lors de l'itération.

  &reftitle.examples;

   Exemple avec Yaf_Config_Ini::key


<?php
/**
 * On suppose que /etc/myapp/application.ini contient :
 * [common]
 * application.name = "MyApp"
 * version          = "1.0"
 */
$config = new Yaf_Config_Ini('/etc/myapp/application.ini', 'common');

for ($config->rewind(); $config->valid(); $config->next()) {
    echo $config->key(), "\n";
}
?>


